const repo = process.argv[2] || "/Users/sourceborn/Documents/ChatGPT/Ash/AshStocks";
const sha = (value) => createHash("sha256").update(value).digest("hex");
const expected = {
  "server-parameter-tunnel-patch.mjs": "dcf63a726ee2bd9c00d39e5f3d6c8293973fbc0589aad86997b304751558ed32",
  "data/parameter-catalog-175.json": "38e608f9f8d2823c9691258d0d655336b76ee40e5ea970012665f05e16f1ebe2",
  "vendor/base-server-37a9e9ceacabd33bc5a2085ad621e368f8fc0cd8.mjs": "156db2e19447e47c5b642a66f6b74f4809763d386d6cc40430b3dd98d264f324",
  "server-upstox-institutional-patch.mjs": "97c583f00f5e6b4daee5ba7ce694f3aa1374a1e25aeb6b76b797a88cb3598777"
};
const source = new Map();
const pins = Object.entries(expected).map(([file, digest]) => {
  const bytes = readFileSync(path.join(repo, file));
  assert.equal(sha(bytes), digest, "Audit source changed; review before updating pin: " + file);
  source.set(file, bytes.toString("utf8"));
  return { file, bytes: bytes.length, sha256: digest, pin_matches: true };
});
const basePath = "vendor/base-server-37a9e9ceacabd33bc5a2085ad621e368f8fc0cd8.mjs";
const base = source.get(basePath);
const patch = source.get("server-parameter-tunnel-patch.mjs");
const catalog = JSON.parse(source.get("data/parameter-catalog-175.json"));
function named(name) {
  const start = base.indexOf("\nfunction " + name + "(");
  assert(start >= 0, "Missing base function: " + name);
  const tail = base.slice(start + 1);
  const end = tail.search(/\n(?:async )?function /);
  assert(end > 0, "Missing function boundary: " + name);
  return tail.slice(0, end);
}
