const begin = patch.indexOf(marker);
assert(begin >= 0 && patch.indexOf(marker, begin + 1) < 0);
const end = patch.indexOf("\n`;\n\nexport function applyParameterTunnelPatches", begin);
assert(end > begin);
const rawHelpers = patch.slice(begin + marker.length, end);
assert.equal((rawHelpers.match(/\$\{/g) || []).length, 1, "Unexpected template interpolation");
assert(rawHelpers.includes("${catalogJson}"));
const helpers = rawHelpers.replace("${catalogJson}", JSON.stringify(catalog));

// Read the actual normalizer replacement literal rather than invent a stub.
const replacementLine = patch.split("\n").find((line) => line.startsWith('    "function normalizeCandles(candles) {\\n'));
assert(replacementLine?.trim().endsWith(","));
const replacement = JSON.parse(replacementLine.trim().slice(0, -1));
const normalizationAnchor = "function normalizeCandles(candles) {";
assert(named("normalizeCandles").includes(normalizationAnchor));
const normalizer = named("normalizeCandles").replace(normalizationAnchor, replacement);
const names = ["numericValue", "clamp", "round", "unique", "applyPortfolio"];
const helperPins = names.map((name) => ({ name, origin: basePath, sha256: sha(named(name)) }));
helperPins.push(
  { name: "normalizeCandles (actual patched wrapper)", origin: basePath + " + server-parameter-tunnel-patch.mjs", sha256: sha(normalizer) },
  { name: "PARAMETER_TUNNEL_FUNCTIONS raw template", origin: "server-parameter-tunnel-patch.mjs", sha256: sha(rawHelpers) },
  { name: "PARAMETER_TUNNEL_FUNCTIONS composed with pinned catalog", origin: "server-parameter-tunnel-patch.mjs + data/parameter-catalog-175.json", sha256: sha(helpers) }
);
let forbiddenCalls = 0;
const forbidden = () => { forbiddenCalls += 1; throw new Error("Offline audit forbids external access"); };
const sandbox = vm.createContext({ fetch: forbidden, getStore: forbidden, currentUpstoxAccessToken: forbidden }, {
  codeGeneration: { strings: false, wasm: false }
});
vm.runInContext(names.map(named).join("\n") + "\n" + normalizer + "\n" + helpers + `
globalThis.subject = {
  data: parameterTunnelData, context: buildParameterTunnelContext,
  node: evaluateParameterTunnelNode, attach: attachParameterTunnel,
  portfolio: applyPortfolio,
  parameter: PARAMETER_TUNNEL_CATALOG.parameters.find((p) => p.id === "NU08")
};`, sandbox, { timeout: 5000 });
const x = sandbox.subject;
assert.equal(x.parameter.formula, "sector_value_after / portfolio_value_after <= 0.25");
const candle = { date: "2026-09-23", open: 100, high: 101, low: 99, close: 100, volume: 100 };
function scenario(name, holdings, proposal, expectedState, expectedValueCondition) {
  const row = { symbol: "SYNTHETIC_CANDIDATE", sector: "Bank", candles: [candle], score: 80,
    decision: "SELECT", gates: { portfolio_caps: true }, proposed_value: proposal };
  const before = JSON.stringify({ row, holdings });
  const context = x.context([row], holdings);
  const node = x.node(x.parameter, row, x.data(row), context);
  const valueBefore = holdings.reduce((sum, h) => sum + h.value, 0);
  const sectorBefore = holdings.filter((h) => h.sector === row.sector).reduce((sum, h) => sum + h.value, 0);
  const valueRatio = (sectorBefore + proposal) / (valueBefore + proposal);
  const attached = x.attach(row, {}, context);
  assert.equal(node.state, expectedState);
  assert.equal(valueRatio <= 0.25, expectedValueCondition);
  assert.equal(attached.decision, row.decision);
  assert.equal(attached.gates.portfolio_caps, row.gates.portfolio_caps);
  assert.equal(JSON.stringify({ row, holdings }), before);
  return { name, currency_for_synthetic_values: "INR", holdings, proposed_sector: row.sector,
    proposed_value: proposal, sector_value_before: sectorBefore, portfolio_position_value_before: valueBefore,
    sector_value_after: sectorBefore + proposal, portfolio_position_value_after: valueBefore + proposal,
    position_value_ratio_after: valueRatio, value_contract_condition: valueRatio <= 0.25,
    node_result: { state: node.state, value: node.value, evidence: node.evidence },
    original_decision: row.decision, attached_decision: attached.decision,
    original_portfolio_cap_gate: true, attached_portfolio_cap_gate: attached.gates.portfolio_caps,
    inputs_unchanged: true };
}
const cases = [
  scenario("False HIT relative to the value-ratio contract", [
    { sector: "Bank", value: 250000 }, ...Array.from({ length: 6 }, () => ({ sector: "Other", value: 125000 }))
  ], 10000, "HIT", false),
  scenario("False MISS relative to the value-ratio contract", [
    { sector: "Bank", value: 1000 }, { sector: "Other", value: 49000 }, { sector: "Other", value: 49000 }
  ], 1000, "MISS", true)
];

// Separate existing value-based scanner allocator, not the NU08 node.
const rows = Array.from({ length: 26 }, (_, i) => ({ symbol: "SYNTHETIC" + String(i).padStart(2, "0"),
  sector: "Bank", score: 100 - i, close: 100, decision: "SELECT", gates: {}, reason: "synthetic fixture" }));
const settings = { startingCapital: 1000000, maxPositionPct: 0.01, regimeMultiplier: 1,
  ifrMultiplier: 1, drawdownMultiplier: 1, maxSectorExposurePct: 25, maxSectorPositions: 500, maxPositions: 500 };
const beforeRows = JSON.stringify(rows);
const allocated = x.portfolio(rows, settings);
assert.equal(allocated.filter((r) => r.decision === "SELECT").length, 25);
assert.equal(allocated.at(-1).decision, "BLOCKED");
assert.equal(allocated.at(-1).gates.portfolio_caps, false);
assert(allocated.at(-1).reason.includes("max sector exposure reached"));
// applyPortfolio shallow-copies rows; its nested gate objects mutate the input.
// This known helper behavior is observed, not repaired, in this offline fixture.
assert.equal(forbiddenCalls, 0);
const institutional = source.get("server-upstox-institutional-patch.mjs");
assert(institutional.includes("score: baseScore") && institutional.includes('"ADVISORY_ONLY"')
  && institutional.includes("primary_rank_preserved: true"));
const self = fileURLToPath(import.meta.url);
const report = {
