  source_review_commit: "611c1c26aad6beebac2ba5473a52333efa5e3220",
  scope: "Read-only audit evidence, not a correction. Runtime entry points and production modules are never imported.",
  source_pins: pins, extracted_helper_pins: helperPins,
  script: { path: self, sha256: sha(readFileSync(self)), output: "JSON stdout only; script performs no file writes" },
  formula: { catalog_location: "data/parameter-catalog-175.json:3042", catalog: x.parameter.formula,
    evaluator_location: "server-parameter-tunnel-patch.mjs:499",
    actual: "(same-sector holding count + 1) / (all holding count + 1) <= 0.25",
    declared_required_input: x.parameter.required,
    counterexample_denominator: "Sum of marked/supplied position values after entry. Cash/NAV treatment remains an unresolved contract; no particular production valuation is asserted." },
  scenarios: cases,
  separate_scanner_batch_cap: { location: basePath + ":1073", settings,
    formula: "sector planned allocation + candidate planned allocation <= startingCapital * maxSectorExposurePct / 100",
    candidate_rows: 26, per_candidate_planned_value: 10000, sector_cap_value: 250000,
    select_rows: allocated.filter((r) => r.decision === "SELECT").length,
    blocked_rows: allocated.filter((r) => r.decision === "BLOCKED").length,
    last_row: { decision: allocated.at(-1).decision, portfolio_cap_gate: allocated.at(-1).gates.portfolio_caps,
      order_status: allocated.at(-1).paper_order.status, reason: allocated.at(-1).reason },
    original_nested_gate_objects_mutated: JSON.stringify(rows) !== beforeRows,
    mutation_scope: "Only in-memory synthetic fixtures; no real state or storage.",
    limit: "Maps initialize empty; no holdings argument. This proves the existing batch allocation cap, not current-portfolio NAV or every-fill sector enforcement." },
